+            .any(|m| m.rotary.is_some() || m.axis.is_some_and(|a| !crate::cl::is_vertical(&a)))
+        {
+            return Some("multiaxis or rotary moves are not supported under a rotated work offset yet");
+        }
+    }
+    None
